Bash(echo "// Task controller for handling task operations and event publishing
// Located in backend/src/controllers/task.controller.ts

import { Request, Response } from ''express'';
import { DaprHelper } from ''../helpers/dapr.helper'';
import { v4 as uuidv4 } from ''uuid'';

interface Task {
  id: string;
  title: string;
  description: string;
  priority: ''high'' | ''medium'' | ''low'';
  dueDate?: string;
  status: ''pending'' | ''in-progress'' | ''completed'';
  userId: string;
}

export class TaskController {
  private static tasks: Task[] = [];

  static async getAllTasks\(req: Request, res: Response\): Promise<void> {
    try {
      res.json\({ tasks: this.tasks }\);
    } catch \(error\) {
      console.error\(''Error getting tasks:'', error\);
      res.status\(500\).json\({ error: ''Internal server error'' }\);
    }
  }

  static async createTask\(req: Request, res: Response\): Promise<void> {
    try {
      const { title, description, priority, dueDate, userId } = req.body;

      // Validate input
      if \(!title || !userId\) {
        res.status\(400\).json\({ error: ''Title and userId are required'' }\);
        return;
      }

      const newTask: Task = {
        id: uuidv4\(\),
        title,
        description: description || '''',
        priority: priority || ''medium'',
        dueDate,
        status: ''pending'',
        userId
      };

      this.tasks.push\(newTask\);

      // Publish task created event
      const eventPayload = {
        eventId: uuidv4\(\),
        eventType: ''task.created'',
        source: ''backend'',
        timestamp: new Date\(\).toISOString\(\),
        data: {
          taskId: newTask.id,
          title: newTask.title,
          description: newTask.description,
          priority: newTask.priority,
          dueDate: newTask.dueDate,
          userId: newTask.userId
        }
      };

      await DaprHelper.publishEvent\(''todo-events'', eventPayload\);

      res.status\(201\).json\({ task: newTask }\);
    } catch \(error\) {
      console.error\(''Error creating task:'', error\);
      res.status\(500\).json\({ error: ''Internal server error'' }\);
    }
  }

  static async updateTask\(req: Request, res: Response\): Promise<void> {
    try {
      const { id } = req.params;
      const { title, description, priority, dueDate, status } = req.body;

      const taskIndex = this.tasks.findIndex\(task => task.id === id\);
      if \(taskIndex === -1\) {
        res.status\(404\).json\({ error: ''Task not found'' }\);
        return;
      }

      // Update task
      const updatedTask = {
        ...this.tasks[taskIndex],
        ...\(title !== undefined && { title }\),
        ...\(description !== undefined && { description }\),
        ...\(priority !== undefined && { priority }\),
        ...\(dueDate !== undefined && { dueDate }\),
        ...\(status !== undefined && { status }\)
      };
      this.tasks[taskIndex] = updatedTask;

      // Publish task updated event
      const eventPayload = {
        eventId: uuidv4\(\),
        eventType: ''task.updated'',
        source: ''backend'',
        timestamp: new Date\(\).toISOString\(\),
        data: {
          taskId: id,
          updates: {
            title,
            description,
            priority,
            dueDate,
            status
          },
          userId: updatedTask.userId
        }
      };

      await DaprHelper.publishEvent\(''todo-events'', eventPayload\);

      res.json\({ task: updatedTask }\);
    } catch \(error\) {
      console.error\(''Error updating task:'', error\);
      res.status\(500\).json\({ error: ''Internal server error'' }\);
    }
  }

  static async deleteTask\(req: Request, res: Response\): Promise<void> {
    try {
      const { id } = req.params;

      const taskIndex = this.tasks.findIndex\(task => task.id === id\);
      if \(taskIndex === -1\) {
        res.status\(404\).json\({ error: ''Task not found'' }\);
        return;
      }

      const deletedTask = this.tasks.splice\(taskIndex, 1\)[0];

      // Publish task deleted event
      const eventPayload = {
        eventId: uuidv4\(\),
        eventType: ''task.deleted'',
        source: ''backend'',
        timestamp: new Date\(\).toISOString\(\),
        data: {
          taskId: id,
          userId: deletedTask.userId
        }
      };

      await DaprHelper.publishEvent\(''todo-events'', eventPayload\);

      res.json\({ message: ''Task deleted successfully'' }\);
    } catch \(error\) {
      console.error\(''Error deleting task:'', error\);
      res.status\(500\).json\({ error: ''Internal server error'' }\);
    }
  }
}")

Bash(echo "// Middleware for handling Dapr pubsub subscriptions
// Located in backend/src/middleware/dapr.middleware.ts

import { Request, Response, NextFunction } from ''express'';

export const daprSubscriptionMiddleware = \(req: Request, res: Response, next: NextFunction\) => {
  // Handle Dapr pubsub subscription validation
  if \(req.headers[''content-type''] === ''application/cloudevents+json''\) {
    // This is a Dapr pubsub event, process accordingly
    console.log\(''Received Dapr pubsub event:'', req.body\);

    // Process the event based on its type
    const event = req.body;
    switch \(event.eventType\) {
      case ''task.created'':
        console.log\(''Processing task created event:'', event.data\);
        break;
      case ''task.updated'':
        console.log\(''Processing task updated event:'', event.data\);
        break;
      case ''task.deleted'':
        console.log\(''Processing task deleted event:'', event.data\);
        break;
      default:
        console.log\(''Unknown event type:'', event.eventType\);
    }
  }

  next\(\);
};")

Bash(echo "// Main backend server file
// Located in backend/src/server.ts

import express, { Request, Response } from ''express'';
import cors from ''cors'';
import { TaskController } from ''./controllers/task.controller'';
import { daprSubscriptionMiddleware } from ''./middleware/dapr.middleware'';

const app = express\(\);
const PORT = process.env.PORT || 8080;

// Middleware
app.use\(cors\(\)\);
app.use\(express.json\(\)\);
app.use\(daprSubscriptionMiddleware\);

// Routes
app.get\(''/'', \(req: Request, res: Response\) => {
  res.json\({ message: ''Evolution of Todo Backend API'' }\);
}\);

app.get\(''/health'', \(req: Request, res: Response\) => {
  res.status\(200\).json\({ status: ''healthy'' }\);
}\);

app.get\(''/ready'', \(req: Request, res: Response\) => {
  res.status\(200\).json\({ status: ''ready'' }\);
}\);

// Task routes
app.get\(''/v1/tasks'', TaskController.getAllTasks\);
app.post\(''/v1/tasks'', TaskController.createTask\);
app.put\(''/v1/tasks/:id'', TaskController.updateTask\);
app.delete\(''/v1/tasks/:id'', TaskController.deleteTask\);

// Dapr pubsub endpoint - this is where Dapr will send events
app.post\(''/v1.0/topics/todo-events'', \(req: Request, res: Response\) => {
  console.log\(''Received event from Dapr pubsub:'', req.body\);

  // Process the event based on its type
  const event = req.body;
  switch \(event.eventType\) {
    case ''task.created'':
      console.log\(''Processing task created event:'', event.data\);
      break;
    case ''task.updated'':
      console.log\(''Processing task updated event:'', event.data\);
      break;
    case ''task.deleted'':
      console.log\(''Processing task deleted event:'', event.data\);
      break;
    default:
      console.log\(''Unknown event type:'', event.eventType\);
  }

  // Respond with 200 to acknowledge receipt
  res.status\(200\).send\(\);
}\);

app.listen\(PORT, \(\) => {
  console.log\(''Backend server is running on port '' + PORT\);
  console.log\(''Dapr sidecar endpoint: http://localhost:3500''\);
}\);")

Bash(echo "// Dapr service client for frontend
// Located in frontend/src/services/dapr.service.ts

class DaprService {
  private readonly daprHttpEndpoint: string;

  constructor\(\) {
    this.daprHttpEndpoint = process.env.REACT_APP_DAPR_HTTP_ENDPOINT || ''http://localhost:3500'';
  }

  async publishEvent\(topic: string, data: any\): Promise<void> {
    try {
      const response = await fetch\(this.daprHttpEndpoint + ''/v1.0/publish/'' + topic, {
        method: ''POST'',
        headers: {
          ''Content-Type'': ''application/json'',
        },
        body: JSON.stringify\(data\),
      }\);

      if \(!response.ok\) {
        throw new Error\(''Failed to publish event: '' + response.statusText\);
      }

      console.log\(''Event published successfully''\);
    } catch \(error\) {
      console.error\(''Failed to publish event:'', error\);
      throw error;
    }
  }

  async invokeService\(serviceAppId: string, serviceMethod: string, data?: any\): Promise<any> {
    try {
      const url = this.daprHttpEndpoint + ''/v1.0/invoke/'' + serviceAppId + ''/method/'' + serviceMethod;
      const options: RequestInit = {
        method: ''POST'',
        headers: {
          ''Content-Type'': ''application/json'',
        },
      };

      if \(data\) {
        options.body = JSON.stringify\(data\);
      }

      const response = await fetch\(url, options\);

      if \(!response.ok\) {
        throw new Error\(''Failed to invoke service: '' + response.statusText\);
      }

      return await response.json\(\);
    } catch \(error\) {
      console.error\(''Failed to invoke service:'', error\);
      throw error;
    }
  }

  async getState\(storeName: string, key: string\): Promise<any> {
    try {
      const response = await fetch\(this.daprHttpEndpoint + ''/v1.0/state/'' + storeName + ''/'' + key\);

      if \(!response.ok\) {
        if \(response.status === 404\) {
          return null; // Key doesn''t exist
        }
        throw new Error\(''Failed to get state: '' + response.statusText\);
      }

      return await response.json\(\);
    } catch \(error\) {
      console.error\(''Failed to get state:'', error\);
      throw error;
    }
  }

  async saveState\(storeName: string, key: string, value: any\): Promise<void> {
    try {
      const response = await fetch\(this.daprHttpEndpoint + ''/v1.0/state/'' + storeName, {
        method: ''POST'',
        headers: {
          ''Content-Type'': ''application/json'',
        },
        body: JSON.stringify\([{
          key,
          value
        }]\),
      }\);

      if \(!response.ok\) {
        throw new Error\(''Failed to save state: '' + response.statusText\);
      }
    } catch \(error\) {
      console.error\(''Failed to save state:'', error\);
      throw error;
    }
  }
}

export default new DaprService\(\);")
